-- parameters: []
SELECT UPPER(lips."MATNR") AS upper, LOWER(lips."VRKME") AS lower, TRIM(lips."VBELN") AS trimmed, (lips."MATNR" || '-' || lips."VRKME") AS joined, COALESCE(lips."VRKME", 'EA') AS fallback, NULLIF(lips."VRKME", '') AS "emptyUnit", (lips."LFIMG" + lips."LFIMG") AS total, (lips."LFIMG" - 1) AS difference, (lips."LFIMG" * 2) AS product, (lips."LFIMG" / 3) AS ratio, ABS(lips."LFIMG") AS magnitude, ROUND(lips."LFIMG", 1) AS rounded, CAST(lips."LFIMG" AS VARCHAR(20)) AS "asText", CAST(lips."MATNR" AS NUMERIC(15,3)) AS "asDecimal", CAST(lips."LFIMG" AS INTEGER) AS "asInteger", CAST(lips."LFIMG" AS DOUBLE PRECISION) AS "asDouble", CAST(lips."VGBEL" AS DATE) AS "asDate", CAST(lips."VGBEL" AS TIMESTAMP) AS "asTimestamp"
FROM "QUERY_IT"."LIPS" lips
